// usageRate from LabFlow TS: share of the 07:00–21:00 opening hours (840 minutes) already booked.
export function usageRate(bookings: readonly { minutes: number }[]): number {
  let rate = 0;
  for (const b of bookings) rate += b.minutes / 840;
  return rate;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { rateFromBody } from '../src/report.ts';

test('a good list', () => assert.equal(rateFromBody('[{"minutes":420},{"minutes":420}]'), 1));
test('minutes as a string is refused', () => assert.equal(rateFromBody('[{"minutes":"60"}]'), 'INVALID_BODY'));
test('a typo is refused', () => assert.equal(rateFromBody('[{"minute":60}]'), 'INVALID_BODY'));
test('an object instead of a list is refused', () => assert.equal(rateFromBody('{"minutes":60}'), 'INVALID_BODY'));
test('negative minutes are refused', () => assert.equal(rateFromBody('[{"minutes":-30}]'), 'INVALID_BODY'));

