import { usageRate } from './usage.ts';

// Prove the shape at runtime instead of promising it with a type assertion.
function isMinutesList(x: unknown): x is { minutes: number }[] {
  return Array.isArray(x) && x.every((b: unknown) =>
    typeof b === 'object' && b !== null && 'minutes' in b &&
    typeof b.minutes === 'number' && b.minutes > 0);
}

export function rateFromBody(body: string): number | 'INVALID_BODY' {
  const data: unknown = JSON.parse(body);
  if (!isMinutesList(data)) return 'INVALID_BODY';
  return usageRate(data);
}

// usageRate from LabFlow TS: share of the 07:00–21:00 opening hours (840 minutes) already booked.
